// codicon 字体本体(woff2 base64,约 38 KB gzip)。单独一个模块,由 codicon-font.ts 的 ensureCodiconFont 动态 import:
// 打包器把它切成单独的块,主包不带它(Monaco 也是单独的字体文件)。由 scripts/gen-codicon-font.py 从 src/assets/codicon.ttf 生成。
export const CODICON_FONT_FACE = `@font-face {
  font-family: "codicon";
  font-display: block;
  src: url(data:font/woff2;base64,) format("woff2");
}`
